#!/usr/bin/env python3
"""One-time publication preparation; removed before the reviewed tree is merged."""
import json
from pathlib import Path
import re
import validate as v

ROOT = Path.cwd()
HEADER = '---\npackage_version: "10.2.0"\nlanguage: "KPS 9.x"\nreviewed: "2026-10-12"\n---\n\n'
# owner, diagram stem, insertion marker, title, alternative text, reading guide, audit reason
PLAN = [
('concepts/skos-concept.md','concepts/concept-and-label','## Use and limits','Different identities can share a label','Two separate concept identities, financial institution and river feature, both have the English label bank','This synthetic vocabulary gives two distinct concepts the same label, bank in English. The arrows mean prefLabel; they do not assert equivalence between the concepts. Compare scope and identity rather than spelling. This is an original illustration of the lexical distinction, not a complete SKOS serialization or a copied W3C figure.','Separate two concept identities from their identical lexical label.'),
('concepts/uniform-resource-identifier.md','concepts/uri-resolution','## Boundary and use','Resolution is not retrieval','A base URI and relative reference resolve to a URI; retrieval and fragment interpretation remain separate','In this synthetic example, base `https://example.org/practices/use-kps.md` plus `../README.md#summary` resolves to `https://example.org/README.md#summary`. The two inputs are needed together. Resolution does not fetch the file or prove that summary is a valid fragment. The representation and viewer determine fragment interpretation; RFC 3986 does not create Markdown heading slugs. The domain and paths are illustrative, not requested network resources.','Distinguish resolving a reference from retrieving a resource and interpreting its fragment.'),
('principles/indirectness-limits-applicability.md','principles/evidence-to-target','## Interpretation','The evidence to target gap','Observed short term surrogate outcome and desired long term functioning require an additional evidential connection','The study and target boxes deliberately differ in outcome and timing. The question between them is an evidential gap, not a proven biological mechanism. A short-term surrogate result may be relevant without directly establishing long-term functioning. State the missing connection and retain uncertainty; this schematic does not assign a GRADE certainty rating, recommend treatment, or reject all indirect evidence.','Expose the unestablished bridge between a measured surrogate and the target outcome.'),
('principles/spacing-effect.md','principles/spacing-variables','## Limits','Different spacing variables','Illustrative interval sets of one one one, two two two, and one two three distinguish total spacing from its distribution','These are synthetic arithmetic examples, not the study schedules or learning results. Four attempts have three gaps: A uses 1 + 1 + 1 units, B uses 2 + 2 + 2, and C uses 1 + 2 + 3. A versus B changes total spacing while keeping an equal-gap pattern; B versus C keeps a total of 6 but changes the pattern. Units are arbitrary. No plan is recommended, and no retention magnitude, superiority or optimal delay is encoded.','Keep total spacing distinct from the pattern of intervals without inventing effect sizes.'),
('models/skos-data-model.md','models/skos-relations','## Illustrative use','Read each vocabulary relationship separately','Concept A has a preferred label, a broader concept, a related concept and a close match in another scheme','This synthetic subset uses four different predicates. A points to B with broader; A and C are related; A has a literal preferred label; D in another scheme is a closeMatch, not an exactMatch. Double-headed edges illustrate symmetry, not causal feedback. The layout asserts no additional relationships: broader is not transitive, and closeMatch is not transitive. The full specification contains constraints omitted from this illustration; a D2 drawing is not proof of SKOS conformance.','Distinguish literal labels, broader and related relations, and cross-scheme mappings.'),
('methods/pico-question-formulation.md','methods/pico-comparison','## Worked illustration','The comparison being asked','Within a specified population, compare an intervention with a comparator on defined outcomes and timing','The two options belong to the same question about a specified population, outcome and assessment time. These arrows organize a review question; they are not random assignment, an observed trial, or a causal-effect estimate. Record what each included study actually investigated separately from the intended question. This original schematic retains the intervention-review meaning rather than silently substituting engineering terms.','Make the intervention and comparator distinction and common outcome explicit before searching.'),
('methods/study-data-extraction.md','methods/independent-extraction','## Working record','Independent extraction before reconciliation','Linked study reports feed two independent extractions which are compared and reconciled using source evidence','For the Cochrane intervention-review outcome-data step, two people work independently from the linked study reports and planned form before comparing results. Agreement retains source locations; disagreement follows the prespecified resolution process. Unsupported values stay unknown. This does not assert that every KPS note requires two reviewers or that agreement proves correctness. Duplicate study-characteristic extraction is desirable but is not the same mandatory condition as duplicate outcome extraction.','Separate independent extraction from comparison and documented disagreement resolution.'),
('methods/cognitive-walkthrough.md','methods/walkthrough-action','## Synthetic example','Inspect every action from the user perspective','For each action inspect intended subgoal, action visibility, goal connection and feedback, then record the predicted difficulty or success','For each action, inspect all four questions using the specified user knowledge and visible cues. An unexplained or negative answer identifies a predicted difficulty, not a measured failure. Record both credible success reasoning and obstacles, then inspect the next action or revise the design. Continue through all four prompts even after predicting a difficulty; this is not a participant test or a numerical usability score.','Make all four learnability questions visible without presenting predictions as observed behavior.'),
('methods/retrieval-practice.md','methods/recall-and-check','## Synthetic example','Keep recall and checking distinct','After studying, put the material aside, preserve an unaided response, then compare it with the source and assess later under a chosen plan','The response is produced with the material put aside, then preserved before correction. Checking against the source identifies omissions; a later assessment has its own purpose and conditions. Do not replace the original response with the corrected one or report current familiarity as delayed retention. This illustrates the local operation summarized above, not an optimal schedule or an exact replication of every study procedure.','Separate unaided recall, subsequent checking, and later assessment.'),
('practices/build-domain-knowledge.md','practices/release-gates','## Current practice summary','Two different release checks','Content review and structural checks must both pass before an authorized repository PR or ZIP is published','This is the local KPS release decision, not a certification procedure. A reader-use gap leads back to content repair, while a structural diagnostic leads to a targeted technical fix. Both must be addressed before the authorized publication action. A repository uses one PR; an absent repository uses a validated ZIP. A paper walkthrough remains a self-review and does not establish reader effectiveness or scientific truth.','Separate content-use review from structural checks and the owner-authorized publication choice.'),
('practices/improve-kps.md','practices/repair-scope','## Stage3 Pilot the repair on real content','Match the repair to its reach','A located problem leads to either a local content repair or a contract and checker change, then a pilot and separate content and structural review','The branches distinguish repair reach, not mutually exclusive causes. A local edit may be enough; changing a governing convention also needs a compatibility and migration assessment. Both routes meet at a real-content pilot. If content still requires guessing or structural tests fail, revise the proposal instead of publishing for the sake of a green dashboard. This is KPS application guidance, not a new external Method.','Distinguish local content repairs from governing-rule changes before a pilot and compatibility check.'),
('practices/review-and-learn.md','practices/attribution-check','## Stage3 Select the smallest warranted revision','Do not turn an outcome into a cause','Check actual execution, changed conditions and distinguishing evidence before updating a causal explanation','This authored review route summarizes Stage2. First verify actual execution. Then note changes that limit attribution and ask whether available evidence distinguishes rival accounts. When it does not, keep the observed result but leave the mechanism unresolved. Distinguishing evidence permits only a scoped update under its assumptions, not universal causation. Multiple concerns can apply at once.','Separate execution failures and inconclusive attribution from a supported scoped update.')
]
SHARES = [
('concepts/provenance.md','models/prov-relations','## Boundary','Production history does not certify truth','A summary entity was produced by an activity using a source entity and associated with an editor agent','The source is used by an activity; its output is generated by that activity, and an agent bears an associated responsibility. The derived-from relation records a dependency, not correctness. This is the same synthetic subset drawn in the PROV Model, embedded here so its meaning is available without opening another file. A faithfully recorded history can still describe an inaccurate output.'),
('concepts/evidence-indirectness.md','principles/evidence-to-target','## Boundary','Evidence and target can differ','A short term surrogate result and a long term functioning question need an additional evidential connection','Here the studied outcome and target outcome differ. A short-term surrogate is not the long-term functioning outcome itself. The unresolved connection explains indirectness without declaring the evidence useless or assigning a certainty rating. This synthetic example preserves the intervention-review scope. The same drawing supports the related Principle without a duplicate source file.')
]

def write(path,text):
    p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def revise(path, transform):
    p=ROOT/path; old=p.read_text(encoding='utf-8'); new=transform(old)
    assert new != old, 'No change: '+path
    write(path,new)

def embed(row):
    owner,stem,marker,title,alt,caption=row[:6]
    path=ROOT/owner; text=path.read_text(encoding='utf-8')
    assert marker in text and f'../diagrams/{stem}.svg' not in text, owner
    heading='**'+title+'**' if owner.startswith('practices/') else '## '+title
    block=f'{heading}\n\n![{alt}](../diagrams/{stem}.svg)\n\n{caption}\n\n[Editable D2 source](../diagrams/{stem}.d2). Source basis and limits remain in this document.\n\n'
    text=text.replace(marker,block+marker,1)
    text=re.sub(r'^version: "[^"]+"','version: "10.2.0"',text,count=1,flags=re.M)
    write(owner,text)

cfg=json.loads((ROOT/'diagrams.json').read_text())
assert len(cfg['diagrams'])==6, 'Unexpected baseline inventory'
old_items=list(cfg['diagrams'])
for row in PLAN:
    assert (ROOT/'diagrams'/ (row[1]+'.d2')).is_file()
    embed(row)
    cfg['diagrams'].append({'source':'diagrams/'+row[1]+'.d2','owner':row[0],'reason':row[6]})
for row in SHARES: embed(row)
write('diagrams.json',json.dumps(cfg,indent=2)+'\n')

roles=('concepts','principles','models','methods','practices')
old_owners={d['owner']:d for d in old_items}
new_owners={r[0]:r for r in PLAN}; shared={r[0]:r for r in SHARES}
audit=[]
for folder in roles:
    for p in sorted((ROOT/folder).glob('*.md')):
        name=p.relative_to(ROOT).as_posix()
        if name in new_owners:
            r=new_owners[name]; decision='add'; sources=['diagrams/'+r[1]+'.d2']; reason=r[6]
        elif name in shared:
            r=shared[name]; decision='reuse'; sources=['diagrams/'+r[1]+'.d2']; reason='Embed the relevant explanation locally without duplicating its editable source.'
        elif name in old_owners:
            r=old_owners[name]; decision='retain'; sources=[r['source']]; reason=r['reason']
        else:
            assert name=='principles/testing-effect.md',name
            decision='text-only'; sources=[]; reason='The scoped finding and contrasting evidence are concise. A generic causal arrow would imply an established mechanism; an effect-size chart requires a separate data extraction and comparison. No decorative chart is added.'
        audit.append({'object':name,'decision':decision,'diagrams':sources,'reason':reason})
write('diagram-audit.json',json.dumps({'reviewed':'2026-10-12','scope':'Core only; current explanatory needs, not a permanent completeness claim','basis_commit':'8fb6d522f5fca2b17376efe6b7eb1d37ba0b0568','objects':audit,'knowledge_graph':{'source':'diagrams/knowledge-map/use-kps-dependencies.d2','decision':'retain','reason':'The existing bounded one-hop view answers its navigation question without full-graph clutter.'}},indent=2)+'\n')
text=HEADER+'# Diagram necessity audit\n\n## Key takeaway\n\nAudit every object for an explanatory gap without requiring every object to contain an image.\n\n## Summary\n\nThe audit retains six source and image pairs, adds twelve explanations and reuses two diagrams in related documents. Nineteen of twenty Core objects embed a relevant explanation. Testing Effect stays text-only for the reason below. The small metadata neighborhood remains secondary. Commit every editable D2 source beside its generated SVG.\n\n## Per object decisions\n\n| Knowledge object | Decision | Explanatory purpose or reason for no diagram |\n|---|---|---|\n'
for item in audit:
    title=re.search(r'^# (.+)',(ROOT/item['object']).read_text(),re.M)[1]
    text+=f"| [{title}]({item['object']}) | {item['decision']} | {item['reason']} |\n"
text+='\n## Reading and review\n\nEach diagram has alternative text, a reading guide, limitations and a source link beside its owning explanation. Arrows mean their labels or the expressly identified local procedure, not proof. The URI and spacing examples are synthetic. Shared visuals have one source each. Practice visuals reveal failure paths and decisions rather than repeating every stage.\n\nThese decisions are an author assessment of current content. Reader evidence can justify changes later; this is not proof that every future visual need is satisfied. See [SOURCE-REVIEW.md](SOURCE-REVIEW.md) for inspected and unavailable sources.\n\n## Maintenance\n\n[diagram-audit.json](diagram-audit.json) records every current Core object. Its tests check coverage, source reuse and image/source links, not explanatory value. [DIAGRAMS.md](DIAGRAMS.md) gives the pinned rendering commands. No independent reader trial or accessibility certification is claimed.\n'
write('DIAGRAM-AUDIT.md',text)

revise('test_diagrams.py',lambda t:t.replace("self.assertEqual(6, len(self.cfg['diagrams']))","self.assertGreater(len(self.cfg['diagrams']), 0)\n        self.assertEqual(len(self.cfg['diagrams']), len({x['source'] for x in self.cfg['diagrams']}))").replace("item = self.cfg['diagrams'][-1]","item = next(x for x in self.cfg['diagrams'] if x.get('metadata_root'))").replace('self.assertEqual(6, self.run_check())',"self.assertEqual(len(self.cfg['diagrams']), self.run_check())").replace('self.assertEqual(6, self.run_check(write=True))',"self.assertEqual(len(self.cfg['diagrams']), self.run_check(write=True))"))
pub=json.loads((ROOT/'publication.json').read_text()); pub['version']='10.2.0';write('publication.json',json.dumps(pub,indent=2)+'\n')
revise('README.md',lambda t:t.replace('10.1.0','10.2.0').replace('Six D2 diagrams support specific reading tasks: study/report distinction, study-level counting, PROV relation directions, PDCA feedback, a Practice decision flow, and one metadata-derived neighborhood.','The [Core-wide necessity audit](DIAGRAM-AUDIT.md) covers all 20 objects. Seventeen explanatory diagrams and one metadata neighborhood are committed as D2 and SVG. Two explanatory sources are reused; Testing Effect stays text-only rather than inventing an effect-size chart.'))
revise('DIAGRAMS.md',lambda t:t.replace('package_version: "10.1.0"','package_version: "10.2.0"').replace('Six selected examples demonstrate different jobs; most Core knowledge files remain text-only.','The [Core-wide audit](DIAGRAM-AUDIT.md) records a decision for all 20 objects, with 17 explanatory sources and one small metadata graph. Shared diagrams have one editable source; there is no per-file quota.').replace('## The selected diagrams','## Original diagrams retained').replace('## Add or revise one diagram','## Additional explanations\n\nNew sources clarify concept labels, URI resolution, indirect evidence, spacing variables, SKOS predicates, PICO comparison, independent extraction, walkthrough prompts, recall records, release gates, repair reach and causal-attribution limits. The [audit](DIAGRAM-AUDIT.md) links each owner and explains reuse and text-only decisions.\n\n## Add or revise one diagram').replace('python test_diagrams.py\n','python test_diagrams.py\npython test_diagram_audit.py\n'))
revise('SOURCE-REVIEW.md',lambda t:re.sub(r'^package_version: "[^"]+"','package_version: "10.2.0"',t,count=1,flags=re.M)+'''\n## Diagram necessity audit in 10 2 0\n\nThe drawings summarize current owning content. On 2026-10-12, the audit rechecked W3C SKOS Sections 3, 5, 8 and 10; RFC 3986 resolution and fragments; Cochrane Chapters 2, 5 and 14 for PICO, independent extraction and indirectness; and the PROV relation subset. The walkthrough report was inspected visually on printed pages 2 and 3 (PDF pages 5 and 6), plus task context on printed page 7. Karpicke and Blunt printed pages 772 and 773 were visually checked for the recall operation. No raw data or effect-size plot was extracted.\n\nThe new PubMed fetch for the spacing article supplied no usable abstract. Its drawing uses only the distinction already retained in the abstract-level Core account and explicitly synthetic arithmetic intervals; this is not fresh full-text verification. Existing empirical qualifications and the Mayrhofer access limit are unchanged.\n\nPractice diagrams visualize existing local decisions, not professional-source requirements. The [per-object audit](DIAGRAM-AUDIT.md) records necessity, reuse and text-only decisions. Content inspection is author review, not an independent reader study.\n''')
write('RELEASE.md',HEADER+'''# Core 10 2 0 diagram completion\n\n## Key takeaway\n\nCommit explanatory D2 sources and SVGs for the gaps identified by a complete Core audit.\n\n## Summary\n\nTwelve new diagrams join six retained pairs, for 18 pairs. Two sources are reused in related documents; one object remains text-only. All 20 knowledge identities, 17 Practice stage titles, 18 References and source-alignment scopes are retained.\n\n## Changes\n\nThe new illustrations clarify identity, reference resolution, evidence applicability, spacing variables, vocabulary relations, comparison structure, independent extraction, learnability, recall records and local Practice decisions. Reading guides, boundaries and editable-source links sit beside the relevant explanation or action. The audit is necessity-based, not an image quota.\n\n## Compatibility\n\nCore content is 10.2.0. The language is KPS 9.x, the structural checker is 9.1.0 and D2 remains 0.9.0. Readers need no renderer or plugin. No knowledge-role reclassification or sibling-domain migration is included.\n\n## Verification and publication\n\nSee [CHECKS.md](CHECKS.md) and [DIAGRAM-AUDIT.md](DIAGRAM-AUDIT.md). The owner authorized one PR targeting main and automatic merge after passing CI. This file does not predeclare remote status. No separate tag or official release is requested.\n''')
write('CHECKS.md',HEADER+'''# Diagram completion verification record\n\n## Key takeaway\n\nSource and render consistency is not evidence of reader effectiveness or scientific truth.\n\n## Summary\n\nThe starting local tree matched GitHub main tree a6ebfcbc90d488c153d4c4e806f5a6297819c16c. The audit covers all 20 objects with 18 D2 and SVG pairs, including one retained metadata graph. All IDs, source scopes and 17 stage titles are retained.\n\n## Reproduce\n\n```bash\npython validate.py .\npython test_validate.py\npython test_alignment.py\npython test_diagrams.py\npython test_diagram_audit.py\npython diagram_tools.py --check\n```\n\nThe diagram policy tests mock CLI execution. The final command separately renders every D2 source with pinned 0.9.0 and compares bytes read-only. The new audit tests check object coverage, reasons, shared sources, embeddings, source links and synthetic arithmetic.\n\n## Content and dependencies\n\nOwners and receiving Practice summaries were inspected for changed meaning before refreshing fingerprints. New reading guides preserve the existing limits. The spacing source was not newly accessible, which is disclosed in SOURCE-REVIEW.md. Diagrams are authored explanations, not copied source figures.\n\n## Limits and execution status\n\nActual renderer, suite and visual-review results are recorded after execution. No independent reader trial, screen-reader audit, native GitHub browser session or scientific reanalysis is claimed. Other domain repositories are untouched.\n''')
revise('.github/workflows/validate.yml',lambda t:t.replace('      - name: Install pinned D2 with verified digest','      - name: Check Core-wide diagram audit\n        run: python3 test_diagram_audit.py\n      - name: Install pinned D2 with verified digest'))
# The author has inspected all modified definitions and the four direct summary consumers.
docs={p:v.parse(p) for p in sorted(ROOT.rglob('*.md')) if not {'.github','.git','__pycache__'}.intersection(p.relative_to(ROOT).parts)}
byid={d.meta['id']:d for d in docs.values() if d.meta.get('id')}
write('summary-dependencies.json',json.dumps(v.snapshot(ROOT,docs,byid),ensure_ascii=False,indent=2)+'\n')
print('Prepared 12 new D2 explanations, 2 reused embeddings and audit of 20 objects')
